; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: cpcfw (Amstrad CPC - firmware text and keys), starts in normal mode
; ============================================================

			DEVICE AMSTRADCPC6128		; for SAVEAMSDOS at the end
			org #0040

NTC_TERM	equ 0		; Option Terminal: 0 none, 1 VT52, 2 ANSI, 3 ADM-3A, 4 Televideo (CP/M)
NTC_TERM_RT	equ 0		; 1: the program calls StdIO.SetTerminal (the terminal is chosen while it runs)
NTC_STRMAX	equ 255		; the longest string (library buffers, temps)
NTC_MEMBANKS	equ 64		; Option Memory: the most 64K banks the Memory class looks for
NTC_ROMENABLE	equ 1		; Option RomEnable (cpcfw, cpcmin): the start code starts the ROMs
NTC_ROMLIB	equ 1		; 1 = the library is the keyword ROM (Library: ROM; ntcRomAsm builds it)
NTC_WINHOLE	equ 0		; 1 = the program is built round an Option Reserve range over the window #4000-#7FFF
NTC_WINPAGED	equ 0		; 1 = page 0 code may sit under the window (Option Memory Paged, not Reserved): the Memory class never hands out page 1 (main RAM's own #4000-#7FFF) when the code reaches past #4000
NTC_BUFSIZE	equ 2048		; the library's buffer (ntc_buf: FileSystem, Memory.Copy): Option Buffer
NTC_ISLN	equ 1		; interrupt classes (Option Class Interrupt): the slots ntc_isl has (8 bytes each)
NTC_INTS	equ 1		; 0 = the platform never lets interrupts in (;@ints 0: ntc_xn's safe point has no ei)
NTC_PLATRSV	equ 0		; 1 = the platform's fixed areas (;@reserved) are Reserved in the memory map: the build goes round them (the old top-of-RAM asserts are off)
NTC_CPMGFX	equ 0		; 1 = CP/M: Graphics draws on an Amstrad CPC's screen (2.2: #C000, Plus: block 1 from common memory)

ntc_start:
			jr ntc_start2
ntc_bk_sp:		dw 0			; #0042: main RAM's SP while a bank runs
ntc_bk_out:
			out (c), c		; #0044: BC = the other side's RAM setting
			jp ntc_bk_land		; #0046: main RAM switched in
ntc_bk_land:
			ld sp, (ntc_bk_sp)
			ret				; to where main RAM handed over
			ASSERT ntc_bk_out == #0044, "the bank switch must be at #0044"
ntc_start2:
			di
			call ntc_rj_find		; Library: ROM - find the ROM, patch the jump block
			jr nc, ntc_rj_ok
			ei
			ret				; no ROM (the message is shown): back to the caller
ntc_rj_ok:
			di				; (KL ROM SELECT lets interrupts in again)
			ld hl, ntc_rj_exit
			push hl			; End comes back here: the caller's ROM selection again
			ld (ntc_csp), sp
			ld a, (#BC77)		; Option RomEnable: start the ROMs again
			cp #DF			; AMSDOS has the cassette calls: they are running
			jp z, ntc_roms_on
			ei
			ld de, #A5F0		; the lowest address the ROMs may use (the keyword ROM's RAM is below)
			ld hl, #ABFF		; the highest (as usual for AMSDOS: it takes about #A700-#ABFF)
			ld c, 7
			call #BCCE		; KL INIT BACK: ROM 7 (DE / HL come back as the new limits)
			inc hl			; the first byte the ROMs took
			ld (ntc_roms_at), hl
			ld de, #A600
			or a
			sbc hl, de
			jp nc, ntc_roms_fit	; AMSDOS alone (or no more): as usual
			ld hl, ntc_roms_msg
			call ntc_roms_puts
			ld a, (ntc_roms_at + 1)
			call ntc_roms_hex
			ld a, (ntc_roms_at)
			call ntc_roms_hex
			ld hl, ntc_roms_msg2
			call ntc_roms_puts
			call #BB06		; KM WAIT CHAR
			rst 0			; (the machine starts again)
ntc_roms_puts:
			ld a, (hl)
			or a
			ret z
			call #BB5A		; TXT OUTPUT
			inc hl
			jr ntc_roms_puts
ntc_roms_hex:
			push af
			rrca
			rrca
			rrca
			rrca
			call ntc_roms_dig
			pop af
ntc_roms_dig:
			and 15
			add a, #90
			daa
			adc a, #40
			daa
			jp #BB5A
ntc_roms_at:	dw 0
ntc_roms_msg:	db "The ROMs' RAM reaches down to #", 0
ntc_roms_msg2:	db ": no room for this program", 13, 10, "(fewer ROMs, or a smaller program)", 13, 10, "Press a key", 13, 10, 0
ntc_roms_fit:
			di
			IF NTC_PLATRSV == 0		; (with the platform's #A600-#BFFF Reserved in the map, the build goes round it)
			ASSERT ntc_free <= #A600, "Option RomEnable: the program and its arrays must end below #A600 (the ROMs take their RAM from #ABFF down)"
			ENDIF
ntc_roms_on:
			ld a, 1
			ld (ntc_nmode), a		; normal mode: waits let interrupts in
			ld sp, main_thread
			ret

; ============================================================
; Main Thread
; ============================================================

main_thread:
			dw kw_bssinit, ntc_bss, ntc_bss_size		; the arrays: do they fit, clear them

			; main.bas 17: Mode 1
			dw kw_model, 1

			; main.bas 18: Print "AMSDOS test on "; System.Platform
			dw kw_printstrvar, str1
			dw kw_printnl

			; main.bas 19: Print "Devices "; FileSystem.Devices(); " - using "; FileSystem.CurrentDevice()
			dw fn_filesystem_devices, var_filesystem_devices_devices
			dw kw_printstrvar, str2
			dw kw_printstrvar, var_filesystem_devices_devices
			dw fn_filesystem_currentdevice, var_filesystem_currentdevice_currentdevice
			dw kw_printstrvar, str3
			dw kw_printstrvar, var_filesystem_currentdevice_currentdevice
			dw kw_printnl

			; main.bas 20: Print "Volumes "; FileSystem.Volumes(); " - using "; FileSystem.CurrentVolume()
			dw fn_filesystem_volumes, var_filesystem_volumes_volumes
			dw kw_printstrvar, str4
			dw kw_printstrvar, var_filesystem_volumes_volumes
			dw fn_filesystem_currentvolume, var_filesystem_currentvolume_currentvolume
			dw kw_printstrvar, str3
			dw kw_printstrvar, var_filesystem_currentvolume_currentvolume
			dw kw_printnl

			; main.bas 21: Wait
			dw p_wait_c

			; main.bas 23: For i = 0 To 9 : a(i) = 1000 - i * 50 : Next
			dw kw_ztov, var_i
for1_t:
			dw kw_mulvl, var_i, 50, tmp2
			dw kw_sublv, 1000, tmp2, tmp1
			dw kw_aset, arr_a, var_i, tmp1
			dw kw_next1l_n, var_i, 9, for1_t
for1_e:

			; main.bas 24: r = FileSystem.Save("AMS1.DAT", VarPtr(a), 20)
			dw fn_filesystem_save, str5, vp_arr_a, lit_20, var_r

			; main.bas 25: Print "Save AMS1.DAT:"; r
			dw kw_printstrvar, str6
			dw kw_printint, var_r
			dw kw_printnl

			; main.bas 26: r = FileSystem.Load("AMS1.DAT", VarPtr(b), 20)
			dw fn_filesystem_load, str5, vp_arr_b, lit_20, var_r

			; main.bas 27: Print "Load AMS1.DAT:"; r; " -"; b(0); " ..."; b(9)
			dw kw_printstrvar, str7
			dw kw_printint, var_r
			dw kw_printstrvar, str8
			dw kw_printint, arr_b
			dw kw_printstrvar, str9
			dw kw_printint, arr_b+18
			dw kw_printnl

			; main.bas 28: t = Ticks
			dw kw_ticks, tmp0
			dw kw_vtov, tmp0, var_t

			; main.bas 29: Frame : Frame
			dw kw_frame
			dw kw_frame

			; main.bas 30: Print "Ticks still counting:"; IIf(Ticks <> t Or System.TicksPerSecond = 0, " yes", " NO")
			dw kw_ticks, tmp0
			dw kw_cpnevv, tmp0, var_t
			dw kw_ftov, tmp0
			dw kw_goto_ifzero_n, tmp0, ch2_0
			dw kw_strcpy, stmp0, str10
			dw ch2_e_go
ch2_0:
			dw kw_strcpy, stmp0, str11
			dw ch2_e_go
ch2_1:
			dw kw_strcpy, stmp0, str12
ch2_e:
			dw kw_printstrvar, str13
			dw kw_printstrvar, stmp0
			dw kw_printnl

			; main.bas 31: Print "A file that isn't there"
			dw kw_printstrvar, str14
			dw kw_printnl

			; main.bas 32: Print "(AMSDOS may print its message):"
			dw kw_printstrvar, str15
			dw kw_printnl

			; main.bas 33: r = FileSystem.Load("NOFILE.DAT", VarPtr(b), 20)
			dw fn_filesystem_load, str16, vp_arr_b, lit_20, var_r

			; main.bas 34: Print "Load NOFILE.DAT:"; r; " (NotFound is -2)"
			dw kw_printstrvar, str17
			dw kw_printint, var_r
			dw kw_printstrvar, str18
			dw kw_printnl

			; main.bas 35: Wait
			dw p_wait_c

			; main.bas 37: Mode 2
			dw kw_model, 2

			; main.bas 38: Print "Mode 2 (80 columns): saving again..."
			dw kw_printstrvar, str19
			dw kw_printnl

			; main.bas 39: r = FileSystem.Save("AMS2.DAT", VarPtr(a), 20)
			dw fn_filesystem_save, str20, vp_arr_a, lit_20, var_r

			; main.bas 40: Print "Save AMS2.DAT:"; r; " - this line should still be 80 columns, under the one above"
			dw kw_printstrvar, str21
			dw kw_printint, var_r
			dw kw_printstrvar, str22
			dw kw_printnl

			; main.bas 41: Wait
			dw p_wait_c

			; main.bas 43: Mode 1
			dw kw_model, 1

			; main.bas 44: Print "B = try drive B, any other key = skip"
			dw kw_printstrvar, str23
			dw kw_printnl

			; main.bas 45: Do While Inkey <> 0 : Loop
do3_t:
			dw kw_inkey, tmp0
			dw kw_cpnevl, tmp0, 0
			dw kw_goto_iffalse_n, do3_e
			dw do3_t_go
do3_e:

			; main.bas 46: Do : k = Inkey : Frame : Loop Until k <> 0
do4_t:
			dw kw_inkey, tmp0
			dw kw_vtov, tmp0, var_k
			dw kw_frame
			dw kw_cpnevl, var_k, 0
			dw kw_goto_iffalse_n, do4_t
do4_e:

			; main.bas 47: If k = 66 Or k = 98 Then
			dw kw_cpeqvl, var_k, 66
			dw kw_ftov, tmp0
			dw kw_cpeqvl, var_k, 98
			dw kw_ftov, tmp1
			dw kw_orvv, tmp0, tmp1, tmp0
			dw kw_goto_ifzero_n, tmp0, if5_1

			; main.bas 48: Print "SelectVolume B:"; FileSystem.SelectVolume("B")
			dw fn_filesystem_selectvolume, str24, var_filesystem_selectvolume_selectvolume
			dw kw_printstrvar, str25
			dw kw_printint, var_filesystem_selectvolume_selectvolume
			dw kw_printnl

			; main.bas 49: r = FileSystem.Save("AMS3.DAT", VarPtr(a), 20)
			dw fn_filesystem_save, str26, vp_arr_a, lit_20, var_r

			; main.bas 50: Print "Save B:AMS3.DAT:"; r
			dw kw_printstrvar, str27
			dw kw_printint, var_r
			dw kw_printnl

			; main.bas 51: r = FileSystem.Load("AMS3.DAT", VarPtr(b), 20)
			dw fn_filesystem_load, str26, vp_arr_b, lit_20, var_r

			; main.bas 52: Print "Load:"; r; " -"; b(0)
			dw kw_printstrvar, str28
			dw kw_printint, var_r
			dw kw_printstrvar, str8
			dw kw_printint, arr_b
			dw kw_printnl

			; main.bas 53: r = FileSystem.SelectVolume("A")
			dw fn_filesystem_selectvolume, str29, var_r

			; main.bas 54: Print "Volumes now "; FileSystem.Volumes()
			dw fn_filesystem_volumes, var_filesystem_volumes_volumes
			dw kw_printstrvar, str30
			dw kw_printstrvar, var_filesystem_volumes_volumes
			dw kw_printnl

			; main.bas 55: End If
if5_1:

			; main.bas 56: Print "done"
			dw kw_printstrvar, str31
			dw kw_printnl

			; main.bas 57: End
			dw kw_printnl0
			dw kw_printstrvar, str32
			dw kw_waitkey
			dw kw_stop

; ============================================================
; sub wait (normal mode)
; ============================================================

p_wait:

			; main.bas 60: Print "Press a key"
			dw kw_printstrvar, str32
			dw kw_printnl

			; main.bas 61: Do While Inkey <> 0 : Loop
do6_t:
			dw kw_inkey, tmp0
			dw kw_cpnevl, tmp0, 0
			dw kw_goto_iffalse_n, do6_e
			dw do6_t_go
do6_e:

			; main.bas 62: Do : Frame : Loop Until Inkey <> 0
do7_t:
			dw kw_frame
			dw kw_inkey, tmp0
			dw kw_cpnevl, tmp0, 0
			dw kw_goto_iffalse_n, do7_t
do7_e:
			dw p_wait_r

; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

ch2_e_go:			ld sp, ch2_e
			jp ntc_xn
do3_t_go:			ld sp, do3_t
			jp ntc_xn
do6_t_go:			ld sp, do6_t
			jp ntc_xn

p_wait_c:		; call wait (normal)
			ld (p_wait_rs), sp
			ld sp, p_wait
			jp ntc_xn
p_wait_r:		; end of wait
			ld sp, (p_wait_rs)
			jp ntc_xn

; ============================================================
; Inline assembly (#asm ... #endasm)
; ============================================================

fn_filesystem_load:		; function load (asm keyword), FileSystem.cls line 64
            pop hl		; FileSystem.cls 65
            ld (fs_a1), hl		; FileSystem.cls 66
            pop hl		; FileSystem.cls 67
            ld e, (hl)		; FileSystem.cls 68
            inc hl		; FileSystem.cls 69
            ld d, (hl)		; FileSystem.cls 70
            ld (fs_a2), de		; FileSystem.cls 71
            pop hl		; FileSystem.cls 72
            ld e, (hl)		; FileSystem.cls 73
            inc hl		; FileSystem.cls 74
            ld d, (hl)		; FileSystem.cls 75
            ld (fs_a3), de		; FileSystem.cls 76
            pop hl		; FileSystem.cls 77
            ld (fs_res), hl		; FileSystem.cls 78
            ld hl, fs_load		; FileSystem.cls 79
            jp fs_go		; FileSystem.cls 80
			ret			; end of #asm

fn_filesystem_save:		; function save (asm keyword), FileSystem.cls line 86
            pop hl		; FileSystem.cls 87
            ld (fs_a1), hl		; FileSystem.cls 88
            pop hl		; FileSystem.cls 89
            ld e, (hl)		; FileSystem.cls 90
            inc hl		; FileSystem.cls 91
            ld d, (hl)		; FileSystem.cls 92
            ld (fs_a2), de		; FileSystem.cls 93
            pop hl		; FileSystem.cls 94
            ld e, (hl)		; FileSystem.cls 95
            inc hl		; FileSystem.cls 96
            ld d, (hl)		; FileSystem.cls 97
            ld (fs_a3), de		; FileSystem.cls 98
            pop hl		; FileSystem.cls 99
            ld (fs_res), hl		; FileSystem.cls 100
            ld hl, fs_save		; FileSystem.cls 101
            jp fs_go		; FileSystem.cls 102
			ret			; end of #asm

fn_filesystem_devices:		; function devices (asm keyword), FileSystem.cls line 298
            pop hl		; FileSystem.cls 299
            ld (fs_res), hl		; FileSystem.cls 300
            ld hl, fs_devices		; FileSystem.cls 301
            jp fs_go0		; FileSystem.cls 302
			ret			; end of #asm

fn_filesystem_currentdevice:		; function currentdevice (asm keyword), FileSystem.cls line 308
            pop hl		; FileSystem.cls 309
            ld (fs_res), hl		; FileSystem.cls 310
            ld hl, fs_curdev		; FileSystem.cls 311
            jp fs_go0		; FileSystem.cls 312
			ret			; end of #asm

fn_filesystem_volumes:		; function volumes (asm keyword), FileSystem.cls line 331
            pop hl		; FileSystem.cls 332
            ld (fs_res), hl		; FileSystem.cls 333
            ld hl, fs_volumes		; FileSystem.cls 334
            jp fs_go0		; FileSystem.cls 335
			ret			; end of #asm

fn_filesystem_currentvolume:		; function currentvolume (asm keyword), FileSystem.cls line 341
            pop hl		; FileSystem.cls 342
            ld (fs_res), hl		; FileSystem.cls 343
            ld hl, fs_curvol		; FileSystem.cls 344
            jp fs_go0		; FileSystem.cls 345
			ret			; end of #asm

fn_filesystem_selectvolume:		; function selectvolume (asm keyword), FileSystem.cls line 351
            pop hl		; FileSystem.cls 352
            ld (fs_a1), hl		; FileSystem.cls 353
            pop hl		; FileSystem.cls 354
            ld (fs_res), hl		; FileSystem.cls 355
            ld hl, fs_selvol		; FileSystem.cls 356
            jp fs_go		; FileSystem.cls 357
			ret			; end of #asm


